import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
def load(n):return json.loads((ROOT/n).read_text().split('=',1)[1].rstrip(';\n'))
DATA=load('data.js');OLD=load('practice-question-data.js')['questions'];BASE=load('studio-flow-data.js')['problems'];SOURCE=load('studio-question-data.js');V2=load('v2-data.js')
def n(v):return format(float(v),'.12g')
def f(v):return format(float(v),'.7g')
def table(headers,rows):return r'\begin{array}{'+'c'*len(headers)+'}'+ '&'.join(r'\text{'+h+'}' for h in headers)+r'\\\hline '+r'\\'.join('&'.join(n(v) if isinstance(v,(int,float,np.number)) else r'\text{'+str(v)+'}' for v in row) for row in rows)+r'\end{array}'
def st(label,*math,text=None,fig=None,values=None):return {'label':label,'math':list(math),'text':[text] if text else [],**({'figure':fig} if fig else {}),**({'values':values} if values else {})}
def txt(label,text):return st(label,text=text)
FIGS={}
def plot(kind,parameters):
 key=hashlib.sha256(json.dumps([kind,parameters],sort_keys=True).encode()).hexdigest()[:14]
 target=ROOT/'assets'/'version-d'/f'{kind}-{key}.svg';target.parent.mkdir(exist_ok=True)
 if str(target) in FIGS:return FIGS[str(target)]
 plt.rcParams.update({'font.size':10,'svg.fonttype':'none'})
 fig,axes=plt.subplots(1,2,figsize=(8,2.9));fig.subplots_adjust(wspace=.34,bottom=.22,top=.86)
 if kind=='discrete':
  xs=np.array(parameters['x']);ps=np.array(parameters['p']);cum=ps.cumsum();lo=min(xs)-.6;hi=max(xs)+.6
  axes[0].vlines(xs,0,ps,color='#236154');axes[0].plot(xs,ps,'o',color='#236154');axes[0].set_ylim(0,max(ps)*1.22);axes[0].set_title('Probability function f(x)')
  edges=[lo,*xs,hi];levels=[0,*cum];
  for i,y in enumerate(levels):
   axes[1].hlines(y,edges[i],edges[i+1],color='#236154')
   if i<len(xs):axes[1].plot(edges[i+1],y,'o',mfc='white',mec='#236154')
   if i>0:axes[1].plot(edges[i],y,'o',color='#236154')
  axes[1].set_ylim(-.06,1.12);axes[1].set_title('Right-continuous CDF F(x)')
 elif kind=='normal':
  mu,sd=parameters['mu'],parameters['sd'];xs=np.linspace(mu-3.6*sd,mu+3.6*sd,450)
  axes[0].plot(xs,stats.norm.pdf(xs,mu,sd),color='#236154');axes[1].plot(xs,stats.norm.cdf(xs,mu,sd),color='#236154')
  for ax in axes:ax.axvline(mu,ls=':',lw=1,color='#777');ax.set_xticks([mu-sd,mu,mu+sd])
  axes[0].set_title('Normal density');axes[1].set_title('Normal CDF');axes[1].set_ylim(-.04,1.04)
 else:
  a,b,c=parameters['a'],parameters['b'],parameters['c'];lo=parameters.get('lo',0);hi=parameters['hi'];span=hi-lo;xs=np.linspace(lo,hi,350)
  ys=a+b*xs;cdf=a*(xs-lo)+b*(xs*xs-lo*lo)/2
  axes[0].plot(xs,ys,color='#236154');axes[0].hlines(0,lo-.18*span,lo,color='#236154');axes[0].hlines(0,hi,hi+.18*span,color='#236154')
  axes[1].plot(xs,cdf,color='#236154');axes[1].hlines(0,lo-.18*span,lo,color='#236154');axes[1].hlines(1,hi,hi+.18*span,color='#236154');axes[1].set_ylim(-.04,1.08)
  axes[0].set_title('Density f(x)');axes[1].set_title('CDF F(x)');
  for ax in axes:ax.set_xticks([lo,(lo+hi)/2,hi])
 for ax in axes:ax.set_xlabel('x');ax.spines[['top','right']].set_visible(False);ax.grid(alpha=.15);ax.set_ylabel('f(x)' if ax is axes[0] else 'F(x)')
 fig.savefig(target,format='svg',metadata={'Date':None});plt.close(fig)
 info={'src':str(target.relative_to(ROOT)),'alt':('Probability mass and right-continuous step CDF' if kind=='discrete' else 'Density and cumulative distribution'),'caption':'Label the horizontal scale and function values; the CDF accumulates to 1.'};FIGS[str(target)]=info;return info

