def math_prose(text):
 def convert(m):
  raw=m[0].replace('≤',r'\le ').replace('≥',r'\ge ').replace('−','-').replace('²','^2').replace('³','^3').replace('⁹','^9').replace('α',r'\alpha ')
  raw=re.sub(r'\bVar\(',lambda _:r'\operatorname{Var}(',raw);raw=re.sub(r'\bSD\(',lambda _:r'\operatorname{SD}(',raw)
  return r'\('+raw+r'\)'
 chunks=re.split(r'(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\])',text)
 pattern=r'P\([^)]*\)|E\[\(X−E\[X\]\)²\]|E\[[^\]]*\]|Var\([A-Z]\)|SD\([A-Z]\)|α\s*=\s*\.?\d+(?:\.\d+)?|10⁹'
 return ''.join(c if c.startswith(('\\(','\\[')) else re.sub(pattern,convert,c) for c in chunks)
for q in list(PROBLEMS.values())+list(SOURCES.values())+list(QUIZZES.values()):
 if 'paragraphs' in q:q['paragraphs']=[math_prose(p) for p in q['paragraphs']]
 if 'parts' in q:q['parts']=[math_prose(p) for p in q['parts']]
